 * 기본 표현식 파싱 (리터럴, 식별자 등)
 */
private parsePrimary(): AST.Expression {
  const token = this.peek();

  // 숫자
  if (token.type === TokenType.NUMBER) {
    this.advance();
    return {
      type: 'Number',
      value: token.value,
      line: token.line,
      column: token.column,
      mode: token.mode,
    };
  }

  // 문자열
  if (token.type === TokenType.STRING) {
    this.advance();
    return {
      type: 'String',
      value: token.value,
      line: token.line,
      column: token.column,
      mode: token.mode,
    };
  }

  // true, false
  if (token.type === TokenType.TRUE || token.type === TokenType.FALSE) {
    this.advance();
    return {
      type: 'Number',
      value: token.type === TokenType.TRUE ? 1 : 0,
      line: token.line,
      column: token.column,
      mode: token.mode,
    };
  }

  // 식별자
  if (token.type === TokenType.IDENTIFIER) {
    this.advance();
    return {
      type: 'Identifier',
      name: token.value,
      line: token.line,
      column: token.column,
      mode: token.mode,
    };
  }

  // 괄호 식
  if (this.match(TokenType.LPAREN)) {
    const expr = this.parseExpression();
    this.consume(TokenType.RPAREN, ') 필요');
    return expr;
  }

  throw new Error(`예상치 못한 토큰: ${token.value} at line ${token.line}`);
}

