/**
 * FreeLang Nexus Phase 9 - 배열 지원 테스트
 */

import NexusLexer from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';

describe('FreeLang Nexus Phase 9 - 배열 지원', () => {
  /**
   * Test 1: 배열 리터럴 파싱 [1, 2, 3]
   */
  test('Test 1: 배열 리터럴 파싱 [1, 2, 3]', () => {
    const code = `@mode(v)
fn test() -> i64 {
  let arr = [1, 2, 3]
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    // AST 검증: 배열 리터럴이 파싱되어야 함
    expect(ast.body.length).toBe(1);
    const fn = ast.body[0] as any;
    expect(fn.type).toBe('VFunction');
    expect(fn.body.length).toBe(1);
    const stmt = fn.body[0] as any;
    expect(stmt.type).toBe('Assign');
    expect(stmt.value.type).toBe('Array');
    expect(stmt.value.elements.length).toBe(3);
  });

  /**
   * Test 2: 빈 배열 파싱 []
   */
  test('Test 2: 빈 배열 파싱 []', () => {
    const code = `@mode(v)
fn test() -> i64 {
  let empty = []
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as any;
    const stmt = fn.body[0] as any;
    expect(stmt.value.type).toBe('Array');
    expect(stmt.value.elements.length).toBe(0);
  });

  /**
   * Test 3: 중첩 표현식 배열 [1+2, 3*4]
   */
  test('Test 3: 중첩 표현식 배열 [1+2, 3*4]', () => {
    const code = `@mode(v)
fn test() -> i64 {
  let arr = [1 + 2, 3 * 4]
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as any;
    const stmt = fn.body[0] as any;
    expect(stmt.value.type).toBe('Array');
    expect(stmt.value.elements.length).toBe(2);
    expect(stmt.value.elements[0].type).toBe('BinaryExpr');
    expect(stmt.value.elements[1].type).toBe('BinaryExpr');
  });

  /**
   * Test 4: 배열 인덱싱 파싱 arr[0]
   */
  test('Test 4: 배열 인덱싱 파싱 arr[0]', () => {
    const code = `@mode(v)
fn test() -> i64 {
  let x = arr[0]
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as any;
    const stmt = fn.body[0] as any;
    expect(stmt.value.type).toBe('ArrayAccess');
    expect(stmt.value.object.type).toBe('Identifier');
    expect((stmt.value.object as any).name).toBe('arr');
    expect(stmt.value.index.type).toBe('Number');
  });

  /**
   * Test 5: V 모드 배열 코드 생성 → C {1, 2, 3}
   */
  test('Test 5: V 모드 배열 코드 생성 → {1, 2, 3}', () => {
    const code = `@mode(v)
fn test() -> i64 {
  let arr = [1, 2, 3]
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('{1, 2, 3}');
  });

  /**
   * Test 6: Python 모드 배열 코드 생성 → [1, 2, 3]
   */
  test('Test 6: Python 모드 배열 코드 생성 → [1, 2, 3]', () => {
    const code = `@mode(python)
def test():
  arr = [1, 2, 3]
  return 0`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.python).toContain('[1, 2, 3]');
  });

  /**
   * Test 7: 배열 인덱싱 코드 생성 → arr[0]
   */
  test('Test 7: 배열 인덱싱 코드 생성 → arr[0]', () => {
    const code = `@mode(v)
fn test() -> i64 {
  let x = arr[0]
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('arr[0]');
  });

  /**
   * Test 8: Trailing comma 지원 [1, 2, 3,]
   */
  test('Test 8: Trailing comma 지원 [1, 2, 3,]', () => {
    const code = `@mode(v)
fn test() -> i64 {
  let arr = [1, 2, 3,]
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as any;
    const stmt = fn.body[0] as any;
    expect(stmt.value.type).toBe('Array');
    expect(stmt.value.elements.length).toBe(3);
  });
});

