    49→// 배열 리터럴 파싱
    50→private parseArrayLiteral(): ArrayLiteral {
    51→  this.expect('[');
    52→  const elements: Expression[] = [];
    53→
    54→  if (!this.check(']')) {
    55→    elements.push(this.parseExpression());
    56→    while (this.match(',')) {
    57→      if (this.check(']')) break; // trailing comma 허용
    58→      elements.push(this.parseExpression());
    59→    }
