    61→
    62→  this.expect(']');
    63→  return { type: 'ArrayLiteral', elements };
    64→}
    65→
    66→// 배열 인덱싱 파싱
    67→private parsePostfix(left: Expression): Expression {
    68→  while (true) {
    69→    if (this.match('[')) {
