   103→```typescript
   104→// 배열 리터럴 → C 코드
   105→private genArrayLiteral(node: ArrayLiteral): string {
   106→  const elements = node.elements.map(e => this.genExpression(e)).join(', ');
   107→  return `{${elements}}`;
   108→}
   109→
   110→// 배열 인덱싱 → C 코드
   111→private genArrayAccess(node: ArrayAccess): string {
   112→  const obj = this.genExpression(node.object);
   113→  const idx = this.genExpression(node.index);
   114→  return `${obj}[${idx}]`;
   115→}
   116→
   117→// 배열 메서드 → C 코드
   118→private genArrayMethod(node: ArrayMethodCall): string {
   119→  const obj = this.genExpression(node.object);
   120→
   121→  switch (node.method) {
   122→    case 'length':
   123→      // C에서는 sizeof로 길이 계산
   124→      return `(sizeof(${obj}) / sizeof(${obj}[0]))`;
   125→
   126→    case 'push':
   127→      // 동적 배열이 필요 (벡터 구현)
   128→      const arg = this.genExpression(node.args[0]);
   129→      return `vector_push(&${obj}, ${arg})`;
   130→
   131→    case 'pop':
   132→      return `vector_pop(&${obj})`;
   133→
   134→    case 'first':
   135→      return `${obj}[0]`;
   136→
   137→    case 'last':
   138→      return `${obj}[sizeof(${obj})/sizeof(${obj}[0])-1]`;
   139→
   140→    default:
   141→      throw new Error(`Unknown array method: ${node.method}`);
   142→  }
   143→}
