/**
 * FreeLang Nexus Phase 10 - While 루프 + 멤버 접근 테스트
 */

import NexusLexer from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';

describe('FreeLang Nexus Phase 10 - While 루프 + 멤버 접근', () => {
  /**
   * Test 1: While 루프 파싱 - AST 노드 타입 확인
   */
  test('Test 1: While 루프 파싱 - WhileStatement AST', () => {
    const code = `@mode(v)
fn test() -> i64 {
  while i < 10 {
    return 0
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as any;
    expect(fn.type).toBe('VFunction');
    expect(fn.body.length).toBe(1);
    const stmt = fn.body[0] as any;
    expect(stmt.type).toBe('WhileStatement');
    expect(stmt.condition).toBeDefined();
    expect(stmt.body).toBeDefined();
  });

  /**
   * Test 2: While 조건 파싱 - BinaryExpr condition
   */
  test('Test 2: While 조건 파싱 - 비교 연산식', () => {
    const code = `@mode(v)
fn test() -> i64 {
  while x > 0 {
    return x
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as any;
    const whileStmt = fn.body[0] as any;
    expect(whileStmt.condition.type).toBe('BinaryExpr');
    expect(whileStmt.condition.operator).toBe('>');
    expect((whileStmt.condition.left as any).name).toBe('x');
  });

  /**
   * Test 3: V 모드 While 코드 생성 - C while 문법
   */
  test('Test 3: V 모드 While 코드 생성 → while (i < 10) {', () => {
    const code = `@mode(v)
fn loop() -> i64 {
  while i < 10 {
    return 0
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('while (');
    expect(result.c).toContain('i < 10');
    expect(result.c).toContain('{');
  });

  /**
   * Test 4: While 본문 내 문장 생성 - println 포함
   */
  test('Test 4: While 본문 내 문장 생성 - println 포함', () => {
    const code = `@mode(v)
fn loop() -> i64 {
  while 1 {
    println("loop")
    return 0
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('printf');
    expect(result.c).toContain('while (');
  });

  /**
   * Test 5: Python 모드 While 코드 생성 - while ...:
   */
  test('Test 5: Python 모드 While 코드 생성 → while ...:', () => {
    const code = `@mode(python)
def run():
  while i < 5 {
    return 0
  }`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.python).toContain('while ');
    expect(result.python).toContain(':');
  });

  /**
   * Test 6: .length 멤버 접근 파싱 - MemberAccess AST
   */
  test('Test 6: .length 멤버 접근 파싱 - MemberAccess AST', () => {
    const code = `@mode(v)
fn test() -> i64 {
  let n = arr.length
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as any;
    const stmt = fn.body[0] as any;
    expect(stmt.type).toBe('Assign');
    expect(stmt.value.type).toBe('MemberAccess');
    expect(stmt.value.property).toBe('length');
    expect((stmt.value.object as any).name).toBe('arr');
  });

  /**
   * Test 7: V 모드 .length 코드 생성 → sizeof 패턴
   */
  test('Test 7: V 모드 .length 코드 생성 → sizeof 패턴', () => {
    const code = `@mode(v)
fn test() -> i64 {
  let n = arr.length
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('sizeof(arr)');
  });

  /**
   * Test 8: While + .length 조합 - 배열 순회 통합 테스트
   */
  test('Test 8: While + .length 조합 - 배열 순회 통합 테스트', () => {
    const code = `@mode(v)
fn iterate() -> i64 {
  while i < arr.length {
    println("item")
    return 0
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('while (');
    expect(result.c).toContain('sizeof(arr)');
    expect(result.c).toContain('printf');
  });
});

