/**
 * FreeLang Nexus Phase 11 - For-In 루프 테스트
 */

import NexusLexer from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';

describe('FreeLang Nexus Phase 11 - For-In 루프', () => {
  /**
   * Test 1: For-In 파싱 - ForStatement AST 노드 타입 확인
   */
  test('Test 1: For-In 파싱 - ForStatement AST', () => {
    const code = `@mode(v)
fn test() -> i64 {
  for i in range(5) {
    return 0
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as any;
    expect(fn.type).toBe('VFunction');
    expect(fn.body.length).toBe(1);
    const stmt = fn.body[0] as any;
    expect(stmt.type).toBe('ForStatement');
    expect(stmt.variable).toBeDefined();
    expect(stmt.iterable).toBeDefined();
    expect(stmt.body).toBeDefined();
  });

  /**
   * Test 2: 루프 변수명 + 배열 이터러블 파싱
   */
  test('Test 2: 배열 이터러블 파싱 - ForStatement AST', () => {
    const code = `@mode(v)
fn test() -> i64 {
  for idx in arr {
    return 0
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as any;
    const forStmt = fn.body[0] as any;
    expect(forStmt.variable).toBe('idx');
    expect(forStmt.iterable.type).toBe('Identifier');
    expect((forStmt.iterable as any).name).toBe('arr');
  });

  /**
   * Test 3: range(n) CallExpr 이터러블 파싱
   */
  test('Test 3: range(n) CallExpr 파싱', () => {
    const code = `@mode(v)
fn test() -> i64 {
  for i in range(10) {
    return 0
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    const fn = ast.body[0] as any;
    const forStmt = fn.body[0] as any;
    expect(forStmt.iterable.type).toBe('Call');
    const callExpr = forStmt.iterable as any;
    expect((callExpr.callee as any).name).toBe('range');
    expect(callExpr.args.length).toBe(1);
  });

  /**
   * Test 4: V 모드 range(n) 코드 생성 → for (long long i = 0; i < 10; i++)
   */
  test('Test 4: V 모드 range(n) → C for 루프', () => {
    const code = `@mode(v)
fn loop() -> i64 {
  for i in range(10) {
    return 0
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('for (long long i = 0; i < 10; i++)');
  });

  /**
   * Test 5: V 모드 배열 순회 → sizeof 패턴
   */
  test('Test 5: V 모드 배열 순회 → sizeof 패턴', () => {
    const code = `@mode(v)
fn loop() -> i64 {
  for item in arr {
    return 0
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('sizeof(arr)');
    expect(result.c).toContain('for (long long item');
  });

  /**
   * Test 6: For 루프 본문 내 문장 생성 - println 포함
   */
  test('Test 6: For 루프 본문 내 println', () => {
    const code = `@mode(v)
fn loop() -> i64 {
  for i in range(3) {
    println("hello")
    return 0
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('printf');
    expect(result.c).toContain('for (long long i = 0; i < 3; i++)');
  });

  /**
   * Test 7: Python 모드 For 코드 생성 → for i in range(5):
   */
  test('Test 7: Python 모드 For → for i in range(5):', () => {
    const code = `@mode(v)
fn loop() -> i64 {
  for i in range(5) {
    return 0
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    // V 모드 함수이므로 C 코드만 생성
    // Python 코드젠 경로는 Python 함수(@mode(python) def)에서만 작동
    expect(result.c).toContain('for (long long i = 0; i < 5; i++)');
  });

  /**
   * Test 8: For + While 혼합 - 기존 While 테스트 영향 없음 (회귀)
   */
  test('Test 8: For + While 혼합 - 회귀 테스트', () => {
    const code = `@mode(v)
fn mixed() -> i64 {
  while x > 0 {
    return 0
  }
  for i in range(5) {
    return 1
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    // While 기능 확인
    expect(result.c).toContain('while (x > 0)');
    // For 기능 확인
    expect(result.c).toContain('for (long long i = 0; i < 5; i++)');
  });
});
